// Package config loads and validates release.toml.
//
// Precedence: CLI flags > MOBILE_RELEASE_* environment variables >
// release.toml > project detection and defaults.
package config

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"github.com/pelletier/go-toml/v2"
)

// CurrentSchemaVersion is the schema written by `mobile-release init`.
const CurrentSchemaVersion = 2

// Project types.
const (
	TypeFlutter = "flutter"
	TypeExpo    = "expo"
	TypeKMP     = "kmp"
	TypeNative  = "native"
)

// PresetJirau marks native projects generated by jirau.
const PresetJirau = "jirau"

// Destinations an environment can publish to.
const (
	DestinationFirebase   = "firebase"   // Firebase App Distribution (Android and iOS)
	DestinationPlay       = "play"       // Google Play track
	DestinationTestFlight = "testflight" // TestFlight
	DestinationAppStore   = "app-store"  // App Store submission for review
	DestinationOTA        = "ota"        // Expo updates
	DestinationArtifacts  = "artifacts"  // build only, copy to artifacts.directory
)

// Build number strategies; any positive integer is also accepted.
const (
	BuildNumberTimestamp = "timestamp" // UTC yyDDDHHMM
	BuildNumberStore     = "store"     // highest number in the target store + 1
	BuildNumberProject   = "project"   // keep the number declared by the project
)

// iOS signing strategies.
const (
	SigningMatch     = "match"     // fastlane match (read-only by default)
	SigningAutomatic = "automatic" // Xcode automatic signing with the App Store Connect key
	SigningManual    = "manual"    // profiles already installed on the machine
)

// Android signing strategies.
const (
	AndroidSigningInjected = "injected" // keystore passed to Gradle as injected signing properties
	AndroidSigningProject  = "project"  // the Gradle project signs by itself
)

// Config is the resolved release.toml.
type Config struct {
	SchemaVersion int                     `toml:"schema_version"`
	Project       Project                 `toml:"project"`
	App           App                     `toml:"app"`
	Android       Android                 `toml:"android"`
	IOS           IOS                     `toml:"ios"`
	Flutter       Flutter                 `toml:"flutter,omitempty"`
	Prepare       Prepare                 `toml:"prepare,omitempty"`
	Environments  map[string]*Environment `toml:"environments"`
	Artifacts     Artifacts               `toml:"artifacts,omitempty"`
}

type Project struct {
	Type   string `toml:"type"`
	Preset string `toml:"preset,omitempty"`
}

type App struct {
	Name string `toml:"name"`
	// ID scopes stored credentials; defaults to the Android package or iOS bundle id.
	ID string `toml:"id,omitempty"`
}

type Android struct {
	Enabled     *bool  `toml:"enabled,omitempty"`
	PackageName string `toml:"package_name,omitempty"`
	ProjectDir  string `toml:"project_dir,omitempty"`
	Signing     string `toml:"signing,omitempty"`
	APKTask     string `toml:"apk_task,omitempty"`
	AABTask     string `toml:"aab_task,omitempty"`
	APKOutput   string `toml:"apk_output,omitempty"`
	AABOutput   string `toml:"aab_output,omitempty"`
	// Track is the default Play track (schema v1 compatibility).
	Track string `toml:"track,omitempty"`
}

type IOS struct {
	Enabled         *bool  `toml:"enabled,omitempty"`
	BundleID        string `toml:"bundle_id,omitempty"`
	TeamID          string `toml:"team_id,omitempty"`
	Workspace       string `toml:"workspace,omitempty"`
	Project         string `toml:"project,omitempty"`
	Scheme          string `toml:"scheme,omitempty"`
	Configuration   string `toml:"configuration,omitempty"`
	Signing         string `toml:"signing,omitempty"`
	SimulatorOutput string `toml:"simulator_output,omitempty"`
	XcodeGenSpec    string `toml:"xcodegen_spec,omitempty"`
}

type Flutter struct {
	Obfuscate      *bool  `toml:"obfuscate,omitempty"`
	SplitDebugInfo string `toml:"split_debug_info,omitempty"`
}

// Prepare holds shell commands run from the project root before builds.
type Prepare struct {
	All     []string `toml:"all,omitempty"`
	Android []string `toml:"android,omitempty"`
	IOS     []string `toml:"ios,omitempty"`
}

type Environment struct {
	Name         string            `toml:"-"`
	Description  string            `toml:"description,omitempty"`
	EnvFile      string            `toml:"env_file,omitempty"`
	Defines      map[string]string `toml:"defines,omitempty"`
	BuildNumber  string            `toml:"build_number,omitempty"`
	Destinations []string          `toml:"destinations"`
	Firebase     Firebase          `toml:"firebase,omitempty"`
	Play         Play              `toml:"play,omitempty"`
	OTA          OTA               `toml:"ota,omitempty"`
	// Confirm requires typing the environment name before publishing.
	Confirm *bool `toml:"confirm,omitempty"`
	// Prepare adds commands that run only for this environment, after the
	// global [prepare] ones of the same step.
	Prepare Prepare `toml:"prepare,omitempty"`
	// Worktree builds in a temporary git worktree of HEAD, so prepare
	// commands never change the developer's checkout.
	Worktree *bool `toml:"worktree,omitempty"`
}

type Firebase struct {
	AndroidAppID string   `toml:"android_app_id,omitempty"`
	IOSAppID     string   `toml:"ios_app_id,omitempty"`
	Groups       []string `toml:"groups,omitempty"`
	Testers      []string `toml:"testers,omitempty"`
}

type Play struct {
	Track         string `toml:"track,omitempty"`
	ReleaseStatus string `toml:"release_status,omitempty"`
}

type OTA struct {
	Mode    string `toml:"mode,omitempty"` // eas | command
	Channel string `toml:"channel,omitempty"`
	Command string `toml:"command,omitempty"`
}

type Artifacts struct {
	Directory string `toml:"directory,omitempty"`
}

// Load reads path. A missing file yields an empty config to be completed by
// detection.
func Load(path string) (Config, error) {
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return Config{SchemaVersion: CurrentSchemaVersion}, nil
	}
	if err != nil {
		return Config{}, err
	}
	return Parse(data)
}

// Parse decodes release.toml, converting schema v1 into v2. Unknown keys are
// rejected so typos do not silently fall back to defaults.
func Parse(data []byte) (Config, error) {
	var probe struct {
		SchemaVersion int `toml:"schema_version"`
	}
	if err := toml.Unmarshal(data, &probe); err != nil {
		return Config{}, fmt.Errorf("release.toml: %w", err)
	}
	var c Config
	if probe.SchemaVersion == 1 {
		var v1 v1Config
		if err := toml.Unmarshal(data, &v1); err != nil {
			return Config{}, fmt.Errorf("release.toml: %w", err)
		}
		c = v1.upgrade()
	} else {
		decoder := toml.NewDecoder(bytes.NewReader(data))
		decoder.DisallowUnknownFields()
		if err := decoder.Decode(&c); err != nil {
			var strict *toml.StrictMissingError
			if errors.As(err, &strict) {
				return Config{}, fmt.Errorf("release.toml: unknown keys:\n%s", strict.String())
			}
			return Config{}, fmt.Errorf("release.toml: %w", err)
		}
	}
	for name, env := range c.Environments {
		if env == nil {
			env = &Environment{}
			c.Environments[name] = env
		}
		env.Name = name
	}
	return c, nil
}

// Marshal renders the config as release.toml.
func Marshal(c Config) ([]byte, error) {
	var buffer bytes.Buffer
	encoder := toml.NewEncoder(&buffer)
	encoder.SetIndentTables(false)
	if err := encoder.Encode(c); err != nil {
		return nil, err
	}
	return buffer.Bytes(), nil
}

// v1Config is the original flat schema, kept for compatibility.
type v1Config struct {
	SchemaVersion int `toml:"schema_version"`
	Project       struct {
		Type string `toml:"type"`
	} `toml:"project"`
	App struct {
		Name        string `toml:"name"`
		Environment string `toml:"environment"`
	} `toml:"app"`
	Android struct {
		PackageName string `toml:"package_name"`
		Track       string `toml:"track"`
		APKTask     string `toml:"apk_task"`
		AABTask     string `toml:"aab_task"`
		APKOutput   string `toml:"apk_output"`
		AABOutput   string `toml:"aab_output"`
	} `toml:"android"`
	IOS struct {
		Workspace       string `toml:"workspace"`
		Scheme          string `toml:"scheme"`
		Configuration   string `toml:"configuration"`
		SimulatorOutput string `toml:"simulator_output"`
	} `toml:"ios"`
	OTA struct {
		Enabled   bool   `toml:"enabled"`
		ServerURL string `toml:"server_url"`
		Channel   string `toml:"channel"`
	} `toml:"ota"`
	Artifacts Artifacts `toml:"artifacts"`
}

func (v v1Config) upgrade() Config {
	track := v.Android.Track
	if track == "" {
		track = "internal"
	}
	env := &Environment{
		BuildNumber:  BuildNumberProject,
		Destinations: []string{DestinationPlay, DestinationTestFlight},
		Play:         Play{Track: track},
	}
	if v.OTA.Enabled {
		env.Destinations = append(env.Destinations, DestinationOTA)
		env.OTA = OTA{Mode: "eas", Channel: v.OTA.Channel}
	}
	return Config{
		SchemaVersion: CurrentSchemaVersion,
		Project:       Project{Type: v.Project.Type},
		App:           App{Name: v.App.Name},
		Android: Android{
			PackageName: v.Android.PackageName,
			Signing:     AndroidSigningProject,
			APKTask:     v.Android.APKTask,
			AABTask:     v.Android.AABTask,
			APKOutput:   v.Android.APKOutput,
			AABOutput:   v.Android.AABOutput,
			Track:       track,
		},
		IOS: IOS{
			Workspace:       v.IOS.Workspace,
			Scheme:          v.IOS.Scheme,
			Configuration:   v.IOS.Configuration,
			SimulatorOutput: v.IOS.SimulatorOutput,
			Signing:         SigningAutomatic,
		},
		Environments: map[string]*Environment{"internal": env},
		Artifacts:    v.Artifacts,
	}
}

// ApplyDefaults fills values that depend on the project type.
func (c *Config) ApplyDefaults() {
	if c.SchemaVersion == 0 {
		c.SchemaVersion = CurrentSchemaVersion
	}
	if c.Artifacts.Directory == "" {
		c.Artifacts.Directory = "dist"
	}
	if c.Android.Signing == "" {
		c.Android.Signing = AndroidSigningInjected
	}
	if c.IOS.Configuration == "" {
		c.IOS.Configuration = "Release"
	}
	if c.IOS.Signing == "" {
		c.IOS.Signing = SigningAutomatic
	}
	switch c.Project.Type {
	case TypeFlutter:
		if c.IOS.Workspace == "" && c.IOS.Project == "" {
			c.IOS.Workspace = "ios/Runner.xcworkspace"
		}
		if c.IOS.Scheme == "" {
			c.IOS.Scheme = "Runner"
		}
		if c.Flutter.SplitDebugInfo == "" {
			c.Flutter.SplitDebugInfo = "build/symbols"
		}
	case TypeExpo, TypeNative:
		if c.Android.ProjectDir == "" {
			c.Android.ProjectDir = "android"
		}
	case TypeKMP:
		if c.Android.ProjectDir == "" {
			c.Android.ProjectDir = "."
		}
	}
	if c.Project.Preset == PresetJirau && c.IOS.XcodeGenSpec == "" {
		c.IOS.XcodeGenSpec = "ios/project.yml"
	}
	if c.App.ID == "" {
		c.App.ID = firstNonEmpty(c.Android.PackageName, c.IOS.BundleID, slug(c.App.Name))
	}
	for _, env := range c.Environments {
		if env.BuildNumber == "" {
			env.BuildNumber = BuildNumberTimestamp
		}
		if env.Play.Track == "" {
			env.Play.Track = firstNonEmpty(c.Android.Track, "internal")
		}
		if env.Play.ReleaseStatus == "" {
			env.Play.ReleaseStatus = "completed"
		}
		if len(env.Firebase.Groups) == 0 && len(env.Firebase.Testers) == 0 {
			env.Firebase.Groups = []string{"internal-testers"}
		}
		if env.OTA.Mode == "" {
			env.OTA.Mode = "eas"
		}
		if env.OTA.Channel == "" {
			env.OTA.Channel = env.Name
		}
	}
}

// ApplyEnv overrides values with MOBILE_RELEASE_* environment variables.
func (c *Config) ApplyEnv(lookup func(string) (string, bool)) {
	set := func(key string, target *string) {
		if value, ok := lookup(key); ok && strings.TrimSpace(value) != "" {
			*target = strings.TrimSpace(value)
		}
	}
	set("MOBILE_RELEASE_PROJECT_TYPE", &c.Project.Type)
	set("MOBILE_RELEASE_APP_NAME", &c.App.Name)
	set("MOBILE_RELEASE_ANDROID_PACKAGE_NAME", &c.Android.PackageName)
	set("MOBILE_RELEASE_ANDROID_APK_TASK", &c.Android.APKTask)
	set("MOBILE_RELEASE_ANDROID_AAB_TASK", &c.Android.AABTask)
	set("MOBILE_RELEASE_ANDROID_APK_OUTPUT", &c.Android.APKOutput)
	set("MOBILE_RELEASE_ANDROID_AAB_OUTPUT", &c.Android.AABOutput)
	set("MOBILE_RELEASE_IOS_BUNDLE_ID", &c.IOS.BundleID)
	set("MOBILE_RELEASE_IOS_TEAM_ID", &c.IOS.TeamID)
	set("MOBILE_RELEASE_IOS_WORKSPACE", &c.IOS.Workspace)
	set("MOBILE_RELEASE_IOS_SCHEME", &c.IOS.Scheme)
	set("MOBILE_RELEASE_IOS_CONFIGURATION", &c.IOS.Configuration)
	set("MOBILE_RELEASE_IOS_SIMULATOR_OUTPUT", &c.IOS.SimulatorOutput)
	set("MOBILE_RELEASE_ARTIFACTS_DIR", &c.Artifacts.Directory)
	if track, ok := lookup("MOBILE_RELEASE_ANDROID_TRACK"); ok && strings.TrimSpace(track) != "" {
		c.Android.Track = strings.TrimSpace(track)
		for _, env := range c.Environments {
			env.Play.Track = c.Android.Track
		}
	}
}

var (
	envNamePattern    = regexp.MustCompile(`^[a-z][a-z0-9-]*$`)
	defineNamePattern = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`)
	teamIDPattern     = regexp.MustCompile(`^[A-Z0-9]{10}$`)
)

// Validate reports every problem found, not only the first.
func (c Config) Validate() error {
	var problems []string
	add := func(format string, args ...any) {
		problems = append(problems, fmt.Sprintf(format, args...))
	}
	if c.SchemaVersion != CurrentSchemaVersion {
		add("unsupported schema_version %d (use %d)", c.SchemaVersion, CurrentSchemaVersion)
	}
	switch c.Project.Type {
	case TypeFlutter, TypeExpo, TypeKMP, TypeNative:
	default:
		add("project.type must be flutter, expo, kmp or native")
	}
	if c.Project.Preset != "" && (c.Project.Preset != PresetJirau || c.Project.Type != TypeNative) {
		add("project.preset %q is only supported as \"jirau\" with type native", c.Project.Preset)
	}
	if c.Artifacts.Directory == "" || filepath.IsAbs(c.Artifacts.Directory) {
		add("artifacts.directory must be a relative path")
	}
	switch c.Android.Signing {
	case AndroidSigningInjected, AndroidSigningProject:
	default:
		add("android.signing must be injected or project")
	}
	switch c.IOS.Signing {
	case SigningMatch, SigningAutomatic, SigningManual:
	default:
		add("ios.signing must be match, automatic or manual")
	}
	if c.IOS.TeamID != "" && !teamIDPattern.MatchString(c.IOS.TeamID) {
		add("ios.team_id must be the 10-character Apple team id")
	}
	if c.IOS.Workspace != "" && c.IOS.Project != "" {
		add("set only one of ios.workspace and ios.project")
	}
	if !c.AndroidEnabled() && !c.IOSEnabled() {
		add("android and ios are both disabled")
	}
	if c.Project.Type == TypeKMP && c.AndroidEnabled() && (c.Android.APKTask == "" || c.Android.AABTask == "") {
		add("kmp projects need android.apk_task and android.aab_task")
	}
	if len(c.Environments) == 0 {
		add("declare at least one [environments.<name>]")
	}
	for _, name := range c.EnvironmentNames() {
		env := c.Environments[name]
		if !envNamePattern.MatchString(name) {
			add("environment %q: use lowercase letters, digits and dashes", name)
		}
		if !validBuildNumber(env.BuildNumber) {
			add("environment %q: build_number must be timestamp, store, project or a positive integer", name)
		}
		for key := range env.Defines {
			if !defineNamePattern.MatchString(key) {
				add("environment %q: invalid define name %q", name, key)
			}
		}
		if env.EnvFile != "" && filepath.IsAbs(env.EnvFile) {
			add("environment %q: env_file must be relative to the project", name)
		}
		if len(env.Destinations) == 0 {
			add("environment %q: declare destinations", name)
		}
		for _, destination := range env.Destinations {
			problems = append(problems, c.destinationProblems(env, destination)...)
		}
	}
	if len(problems) > 0 {
		return &ValidationError{Problems: problems}
	}
	return nil
}

func (c Config) destinationProblems(env *Environment, destination string) []string {
	prefix := fmt.Sprintf("environment %q, destination %q: ", env.Name, destination)
	var problems []string
	switch destination {
	case DestinationFirebase:
		if c.AndroidEnabled() && env.Firebase.AndroidAppID == "" {
			problems = append(problems, prefix+"set firebase.android_app_id")
		}
		if c.IOSEnabled() && env.Firebase.IOSAppID == "" {
			problems = append(problems, prefix+"set firebase.ios_app_id")
		}
	case DestinationPlay:
		if !c.AndroidEnabled() {
			problems = append(problems, prefix+"android is disabled")
		}
		if c.Android.PackageName == "" {
			problems = append(problems, prefix+"set android.package_name")
		}
	case DestinationTestFlight, DestinationAppStore:
		if !c.IOSEnabled() {
			problems = append(problems, prefix+"ios is disabled")
		}
		if c.IOS.BundleID == "" {
			problems = append(problems, prefix+"set ios.bundle_id")
		}
	case DestinationOTA:
		if c.Project.Type != TypeExpo {
			problems = append(problems, prefix+"OTA updates are only supported for expo projects")
		}
		if env.OTA.Mode != "eas" && env.OTA.Mode != "command" {
			problems = append(problems, prefix+"ota.mode must be eas or command")
		}
		if env.OTA.Mode == "command" && strings.TrimSpace(env.OTA.Command) == "" {
			problems = append(problems, prefix+"ota.command is required when ota.mode = \"command\"")
		}
	case DestinationArtifacts:
	default:
		problems = append(problems, prefix+"unknown destination (use firebase, play, testflight, app-store, ota or artifacts)")
	}
	if destination == DestinationFirebase || destination == DestinationTestFlight || destination == DestinationAppStore {
		if c.IOSEnabled() && c.IOS.Signing == SigningMatch && c.IOS.TeamID == "" {
			problems = append(problems, prefix+"ios.signing = \"match\" needs ios.team_id")
		}
	}
	return problems
}

// ValidationError lists every configuration problem.
type ValidationError struct {
	Problems []string
}

func (e *ValidationError) Error() string {
	return "invalid release.toml:\n  - " + strings.Join(e.Problems, "\n  - ")
}

func validBuildNumber(value string) bool {
	switch value {
	case BuildNumberTimestamp, BuildNumberStore, BuildNumberProject:
		return true
	}
	number, err := strconv.Atoi(value)
	return err == nil && number > 0
}

// AndroidEnabled reports whether Android builds are part of this project.
func (c Config) AndroidEnabled() bool {
	if c.Android.Enabled != nil {
		return *c.Android.Enabled
	}
	return true
}

// IOSEnabled reports whether iOS builds are part of this project.
func (c Config) IOSEnabled() bool {
	if c.IOS.Enabled != nil {
		return *c.IOS.Enabled
	}
	return true
}

// FlutterObfuscate defaults to true.
func (c Config) FlutterObfuscate() bool {
	if c.Flutter.Obfuscate != nil {
		return *c.Flutter.Obfuscate
	}
	return true
}

// EnvironmentNames returns the environments in a stable order.
func (c Config) EnvironmentNames() []string {
	names := make([]string, 0, len(c.Environments))
	for name := range c.Environments {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// Environment returns the named environment.
func (c Config) Environment(name string) (*Environment, error) {
	env, ok := c.Environments[name]
	if !ok {
		return nil, fmt.Errorf("unknown environment %q (available: %s)", name, strings.Join(c.EnvironmentNames(), ", "))
	}
	return env, nil
}

// Has reports whether the environment publishes to destination.
func (e *Environment) Has(destination string) bool {
	for _, value := range e.Destinations {
		if value == destination {
			return true
		}
	}
	return false
}

// UsesWorktree reports whether builds run in a temporary worktree.
func (e *Environment) UsesWorktree() bool {
	return e != nil && e.Worktree != nil && *e.Worktree
}

// NeedsConfirmation defaults to true for environments that publish to stores.
func (e *Environment) NeedsConfirmation() bool {
	if e.Confirm != nil {
		return *e.Confirm
	}
	return e.Has(DestinationPlay) || e.Has(DestinationTestFlight) || e.Has(DestinationAppStore)
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return strings.TrimSpace(value)
		}
	}
	return ""
}

func slug(value string) string {
	value = strings.ToLower(strings.TrimSpace(value))
	var builder strings.Builder
	dash := false
	for _, r := range value {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') {
			builder.WriteRune(r)
			dash = false
			continue
		}
		if !dash && builder.Len() > 0 {
			builder.WriteByte('-')
			dash = true
		}
	}
	return strings.Trim(builder.String(), "-")
}
